      "MADEIRA GARN. French Heirloom Embroidery and Edge Finishing Masterclass. Freiburg, 2023.",
      "ARTRELADOS. Guia de Bordados Nobres para Cama, Mesa e Banho de Luxo. Curitiba, 2024."
